#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: Tailscale — Mac ↔ serveur ArgOS derrière la box
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6
ENV_FILE="${HOME}/.argos-tailscale.env"
SSH_KEY="${HOME}/.ssh/argos_wap"
SSH_USER="argos"
SSH_HOST_ALIAS="argos"

banner "Tailscale · accès SSH au serveur depuis internet"

# ── 1. Compte Tailscale ───────────────────────────────────────────────────
stage "Compte Tailscale"
say "Il te faut un compte Tailscale (gratuit pour usage perso)."
open_url "https://login.tailscale.com/start"
step "Crée un compte (Google / Microsoft / GitHub / e-mail) ou connecte-toi."
step "Quand le tableau de bord Machines s'affiche, tu es prêt."
pause "Compte prêt ? Entrée pour continuer"

# ── 2. Installer Tailscale sur le Mac ─────────────────────────────────────
stage "Installer Tailscale sur ce Mac"
if [[ -d /Applications/Tailscale.app ]]; then
  say "Tailscale.app est déjà installé."
else
  say "Installation via Homebrew (mot de passe Mac demandé pour sudo)."
  step "Si brew échoue, télécharge depuis https://tailscale.com/download/mac"
  if confirm "Lancer brew install --cask tailscale maintenant"; then
    brew install --cask tailscale
  else
    open_url "https://tailscale.com/download/mac"
    pause "Quand Tailscale.app est dans /Applications, Entrée"
  fi
fi
if [[ ! -d /Applications/Tailscale.app ]]; then
  warn "Tailscale.app introuvable — relance le wizard après l'install."
  exit 1
fi

# ── 3. Connecter le Mac au tailnet ────────────────────────────────────────
stage "Connecter ce Mac"
say "On ouvre l'app ; tu t'authentifies avec le même compte."
open -a Tailscale || true
step "Barre de menu → icône Tailscale → Log in (si pas déjà connecté)."
step "Autorise dans le navigateur, reviens ici."
pause "Mac connecté (icône Tailscale active) ? Entrée"
if command -v tailscale >/dev/null 2>&1; then
  note "État Mac :"
  tailscale status 2>/dev/null | head -20 || true
  MAC_IP=$(tailscale ip -4 2>/dev/null || true)
  [[ -n "${MAC_IP:-}" ]] && note "IP Tailscale de ce Mac : $MAC_IP"
else
  note "CLI tailscale absente (normal selon l'install) — l'app barre de menu suffit."
fi

# ── 4. Installer Tailscale sur le serveur Ubuntu ──────────────────────────
stage "Installer Tailscale sur le serveur"
ask SERVER_LAN_IP "IP LAN du serveur (ex. 192.168.1.116) :"
[[ -z "${SERVER_LAN_IP:-}" ]] && SERVER_LAN_IP="192.168.1.116"
write_env SERVER_LAN_IP "$SERVER_LAN_IP"

if [[ ! -f "$SSH_KEY" ]]; then
  warn "Clé $SSH_KEY introuvable. Indique une autre clé."
  ask SSH_KEY "Chemin de la clé privée SSH :"
fi

say "Test SSH vers ${SSH_USER}@${SERVER_LAN_IP} …"
if ! ssh -i "$SSH_KEY" -o StrictHostKeyChecking=accept-new -o ConnectTimeout=8 \
  -o BatchMode=yes "${SSH_USER}@${SERVER_LAN_IP}" 'echo OK'; then
  warn "SSH refusé. Vérifie : Mac sur le wifi de la box, IP, clé."
  exit 1
fi
say "SSH OK."

say "Installation officielle Tailscale sur Ubuntu (sudo sur le serveur)."
step "Le mot de passe sudo du compte ${SSH_USER} va être demandé."
ssh -t -i "$SSH_KEY" "${SSH_USER}@${SERVER_LAN_IP}" \
  'curl -fsSL https://tailscale.com/install.sh | sh'

# ── 5. Authentifier le serveur ────────────────────────────────────────────
stage "Authentifier le serveur"
say "On lance tailscale up ; une URL d'auth s'affiche."
step "Ouvre l'URL dans le navigateur de CE Mac (même compte Tailscale)."
step "Approuve la machine serveur, reviens ici."
pause "Prêt à lancer sudo tailscale up sur le serveur ?"

# Capture possible login URL from output (best-effort)
AUTH_OUT=$(mktemp)
ssh -t -i "$SSH_KEY" "${SSH_USER}@${SERVER_LAN_IP}" \
  'sudo tailscale up' 2>&1 | tee "$AUTH_OUT" || true

if grep -qoE 'https://login\.tailscale\.com/[^[:space:]]+' "$AUTH_OUT"; then
  AUTH_URL=$(grep -oE 'https://login\.tailscale\.com/[^[:space:]]+' "$AUTH_OUT" | head -1)
  say "URL détectée — ouverture navigateur."
  open_url "$AUTH_URL"
fi
rm -f "$AUTH_OUT"
pause "Serveur approuvé dans le dashboard Tailscale ? Entrée"

SERVER_TS_IP=$(ssh -i "$SSH_KEY" "${SSH_USER}@${SERVER_LAN_IP}" \
  'tailscale ip -4' 2>/dev/null | head -1 | tr -d '[:space:]' || true)
if [[ -z "${SERVER_TS_IP:-}" ]]; then
  ask SERVER_TS_IP "IP Tailscale du serveur (Machines → serveur → IPv4) :"
else
  say "IP Tailscale du serveur : $SERVER_TS_IP"
fi
write_env SERVER_TS_IP "$SERVER_TS_IP"

# ── 6. SSH config + vérif ─────────────────────────────────────────────────
stage "Configurer SSH et vérifier"
SSH_CONFIG="${HOME}/.ssh/config"
mkdir -p "${HOME}/.ssh"
chmod 700 "${HOME}/.ssh"
touch "$SSH_CONFIG"
chmod 600 "$SSH_CONFIG"

if grep -qE "^Host[[:space:]]+${SSH_HOST_ALIAS}([[:space:]]|\$)" "$SSH_CONFIG" 2>/dev/null; then
  say "Un Host ${SSH_HOST_ALIAS} existe déjà dans ~/.ssh/config — on ne l'écrase pas."
  note "Vérifie qu'il pointe vers ${SERVER_TS_IP} avec IdentityFile ${SSH_KEY}"
else
  if confirm "Ajouter Host ${SSH_HOST_ALIAS} → ${SERVER_TS_IP} dans ~/.ssh/config"; then
    {
      printf '\n# ArgOS via Tailscale (wizard-tailscale)\n'
      printf 'Host %s\n' "$SSH_HOST_ALIAS"
      printf '  HostName %s\n' "$SERVER_TS_IP"
      printf '  User %s\n' "$SSH_USER"
      printf '  IdentityFile %s\n' "$SSH_KEY"
    } >> "$SSH_CONFIG"
    say "Entrée ajoutée."
  fi
fi

say "Test SSH via Tailscale …"
if ssh -i "$SSH_KEY" -o ConnectTimeout=10 -o BatchMode=yes \
  "${SSH_USER}@${SERVER_TS_IP}" 'hostname; tailscale status | head -5'; then
  say "Connexion SSH via Tailscale OK."
else
  warn "Échec — attends quelques secondes, vérifie Machines sur login.tailscale.com"
  open_url "https://login.tailscale.com/admin/machines"
fi

say "Depuis n'importe où (Tailscale connecté sur le Mac) :"
note "  ssh ${SSH_HOST_ALIAS}"
note "  ou : ssh -i ${SSH_KEY} ${SSH_USER}@${SERVER_TS_IP}"
note "Tunnel UI ArgOS : ssh -L 8443:127.0.0.1:443 ${SSH_HOST_ALIAS}"
note "Puis https://localhost:8443"

finish
note "Astuce : hors maison, ouvre Tailscale sur le Mac avant le ssh."
note "Rien à ouvrir sur la box (pas de port 22)."
